#define MAX_STEPS 100
#define MAX_DIST 20.
#define SURF_DIST .001

#define FOG_START 10.
#define FOG_END 20.

#define BG_COLOR vec3(135, 206, 235)
#define OBJ_COLOR vec3(0,255,25)

#define GLOW_DIST .1
#define GLOW_COL vec3(255,255,255)

#define S smoothstep
#define T iTime

vec3 camPos = vec3(0,0,0);

struct MarchData  {
    float mindistance;
    bool didCollide;
    bool doGlow;
    float distanceTravelled;
    int steps;
    vec3 color;
    float minDist;
};

mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}
float clmp(float a,float b,float h) {
    if(h<=a)return a;
    if(h>=b)return b;
    return h;
}
float fogAmount(float d) {
    return clmp(0.,FOG_END-FOG_START,d-FOG_START)/(FOG_END-FOG_START);
}

vec4 sdSphere(vec3 p)
{
  vec3 col = vec3(0,255,0);

  //float p2 = T-2.0;
  //float d = length(vec3(p.x-(3.0*sin((2.0*3.14159265*p2)/3.0)),p.y,p.z))-float(1.);
  float d = length(p)-float(1.);
  return vec4(col,d);
}

vec4 sdRect(vec3 p, vec3 b)
{
  vec3 col = vec3(255,0,0);

  vec3 q = abs(p) - b;
  float d = length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
  return vec4(vec3(col),d);
}
vec4 sdFractal(vec3 p)
{
  vec3 col = vec3(0,255,0);
  vec3 np = vec3(mod(p.x, 3.)-1.5,mod(p.y, 3.)-1.5,mod(p.z, 3.)-1.5);

  float d = length(np)-float(1.);
  return vec4(col,d);
}
vec4 sdPlane(vec3 p) {
    vec3 col = vec3(0,220,100);

    float dist = p.y+1.3;

    return vec4(col,dist);
}

vec4 sdTorus(vec3 p) {
    vec2 t = vec2(1.,.3);

    float dist = length(vec2(length(vec2(p.x, p.z))-t.x,p.y))-t.y;

    vec3 col = vec3(255, 255, 0);

    return vec4(col,dist);
}

vec4 sierpinskiTetrahedron(vec3 p) {
    vec3 col = vec3(127,127,127);

    vec3 z = p;
    float Scale = 2.;

    vec3 a1 = vec3(1,1,1);
	vec3 a2 = vec3(-1,-1,1);
	vec3 a3 = vec3(1,-1,-1);
	vec3 a4 = vec3(-1,1,-1);
	vec3 c;
	int n = 0;
	float dist, d;
	while (n < 20) {
		 c = a1; dist = length(z-a1);
	        d = length(z-a2); if (d < dist) { c = a2; dist=d; }
		 d = length(z-a3); if (d < dist) { c = a3; dist=d; }
		 d = length(z-a4); if (d < dist) { c = a4; dist=d; }
		z = Scale*z-c*(Scale-1.0);
		n++;
	}

	float DE = length(z) * pow(Scale, float(-n));
    return vec4(col,DE);
}

vec4 smin(vec4 a, vec4 b, float k) {
    float h = clamp(0.5 + 0.5*(a.w-b.w)/k, 0.0, 1.0);
    vec3 color = vec3(mix(a.x, b.x, h),mix(a.y, b.y, h),mix(a.z, b.z, h)); 
    float dist = mix(a.w, b.w, h) - k*h*(1.0-h);
    return vec4(color,dist);
}
vec4 smax(vec4 a, vec4 b, float k) {
   return -smin(-a,-b,k);
}

vec4 GetDist(vec3 p) {
    float s = .3;

    vec4 d1 = smin(sdSphere(vec3(p.x+1.8,p.y,p.z)),sdRect(vec3(p.x-1.3,p.y,p.z-.7),vec3(1,1,2)),s);
    return smin(sdTorus(p),d1,s);
}

MarchData RayMarch(vec3 ro, vec3 rd) {
    MarchData _dat=MarchData(0., false, false, 0., 0, vec3(127), GLOW_DIST);
    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*_dat.distanceTravelled;
        float dS = GetDist(p).w;
        _dat.distanceTravelled += dS;
        _dat.steps += 1;
        _dat.color = vec3(GetDist(p));

        if(dS<_dat.minDist) _dat.minDist=dS;

        if(_dat.distanceTravelled<MAX_DIST && abs(dS)<SURF_DIST) {
            _dat.didCollide = true;
            return _dat;
        }
    }

    if (_dat.minDist < GLOW_DIST && !_dat.didCollide) _dat.doGlow = true;
    return _dat;
}

vec3 GetNormal(vec3 p) {
	float d = GetDist(p).w;
    vec2 e = vec2(.001, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy).w,
        GetDist(p-e.yxy).w,
        GetDist(p-e.yyx).w);

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 m = iMouse.xy/iResolution.xy;

    vec3 ro = vec3(0, 4, -3)+camPos;
    ro.yz *= Rot(-m.y*3.14+1.);
    ro.xz *= Rot(-m.x*6.2831);

    vec3 rd = GetRayDir(uv, ro, vec3(0,0.,0), 1.)+camPos;
    vec3 col = BG_COLOR/255.;

    MarchData _dat = RayMarch(ro, rd);

    if(_dat.didCollide) {
        vec3 p = ro + rd * _dat.distanceTravelled;
        vec3 n = GetNormal(p);
        vec3 r = reflect(rd, n);

        float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        col = vec3(dif)*(_dat.color/255.);
    }
    if (_dat.doGlow) {
        col = GLOW_COL;
    }

    //col = mix(col, BG_COLOR/255., fogAmount(_dat.distanceTravelled));
    col = pow(col, vec3(.4545));	// gamma correction

    fragColor = vec4(col,1.0);
}
